import torch, time, ctypes, b200probe as bp, statistics as st
from cuda.bindings import driver as D
SRC = r'''
__device__ __forceinline__ float silu_bw(float g, float x, float s) {
    return __fmul_rn(g, __fmul_rn(s, __fadd_rn(1.0f, __fmul_rn(x, __fsub_rn(1.0f, s)))));
}
__device__ __forceinline__ float4 ld4(const float* p, unsigned long long pol) {
    float4 v; asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;" : "=f"(v.x), "=f"(v.y), "=f"(v.z), "=f"(v.w) : "l"(p), "l"(pol)); return v; }
__device__ __forceinline__ void st4(float* p, float4 v, unsigned long long pol) {
    asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(p), "f"(v.x), "f"(v.y), "f"(v.z), "f"(v.w), "l"(pol) : "memory"); }
extern "C" __global__ void k(const float* __restrict__ g, const float* __restrict__ x, const float* __restrict__ s, float* __restrict__ o, unsigned n) {
    const unsigned nvec = n >> 2;
    const unsigned i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < nvec) {
        float4 a = ld4(g + 4*i, 0x12F0000000000000ull), b = ld4(x + 4*i, 0x12F0000000000000ull), c = ld4(s + 4*i, 0x12F0000000000000ull);
        float4 r; r.x = silu_bw(a.x,b.x,c.x); r.y = silu_bw(a.y,b.y,c.y); r.z = silu_bw(a.z,b.z,c.z); r.w = silu_bw(a.w,b.w,c.w);
        st4(o + 4*i, r, 0x14F0000000000000ull);
    } else if (i == nvec) {
        const unsigned e = nvec << 2; float ta[3], tb[3], tc[3];
        #pragma unroll
        for (int q = 0; q < 3; ++q) if (e + q < n) { ta[q] = g[e+q]; tb[q] = x[e+q]; tc[q] = s[e+q]; }
        #pragma unroll
        for (int q = 0; q < 3; ++q) if (e + q < n) o[e+q] = silu_bw(ta[q], tb[q], tc[q]);
    }
}'''
K = bp.cuda_kernel(SRC, "k")
bp._ok(D.cuFuncSetAttribute(K.fn, D.CUfunction_attribute.CU_FUNC_ATTRIBUTE_NON_PORTABLE_CLUSTER_SIZE_ALLOWED, 1), "np")
A = D.CUlaunchAttributeID
def mk(T, C, coop=False):
    cfgs = {}
    def get(n):
        if n in cfgs: return cfgs[n]
        nt = (n >> 2) + (1 if n & 3 else 0)
        grid = (nt + T - 1) // T
        if C: grid = (grid + C - 1) // C * C
        cfg = D.CUlaunchConfig(); cfg.gridDimX, cfg.gridDimY, cfg.gridDimZ = grid, 1, 1
        cfg.blockDimX, cfg.blockDimY, cfg.blockDimZ = T, 1, 1; cfg.sharedMemBytes = 0
        al = []
        if C:
            a = D.CUlaunchAttribute(); a.id = A.CU_LAUNCH_ATTRIBUTE_CLUSTER_DIMENSION
            a.value.clusterDim.x, a.value.clusterDim.y, a.value.clusterDim.z = C, 1, 1; al.append(a)
        if coop:
            a = D.CUlaunchAttribute(); a.id = A.CU_LAUNCH_ATTRIBUTE_COOPERATIVE; a.value.cooperative = 1; al.append(a)
        cfg.attrs = al; cfg.numAttrs = len(al); cfgs[n] = cfg; return cfg
    def launch(g, x, s, o):
        n = g.numel(); cfg = get(n)
        cfg.hStream = D.CUstream(torch.cuda.current_stream().cuda_stream)
        args = ((g.data_ptr(), x.data_ptr(), s.data_ptr(), o.data_ptr(), n), (ctypes.c_void_p,)*4 + (ctypes.c_uint32,))
        err, = D.cuLaunchKernelEx(cfg, K.fn, args, 0); assert int(err) == 0, err
    return launch
V = {"P": mk(256,0), "C1": mk(256,1), "C2": mk(256,2), "C8": mk(256,8), "C16": mk(256,16),
     "C1coop": mk(256,1,True), "C16coop": mk(256,16,True), "C1_t128": mk(128,1), "C16_t64": mk(64,16)}
# correctness
for n in (131, 4096):
    g,x,s = (torch.randn(n, device="cuda") for _ in range(3)); ref = g*(s*(1+x*(1-s)))
    for nm,f in V.items():
        o = torch.zeros(n, device="cuda"); f(g,x,s,o); torch.cuda.synchronize(); assert torch.equal(o, ref), (nm, n)
sizes = [131, 2053, 4096, 16384]
res = {(nm,n): [] for nm in V for n in sizes}
data = {n: [torch.randn(n, device="cuda") for _ in range(3)] + [torch.zeros(n, device="cuda")] for n in sizes}
for r in range(9):
    for n in sizes:
        g,x,s,o = data[n]
        for nm,f in V.items():
            res[(nm,n)].append(bp.harness_time(f, [g,x,s],[o]))
print("variant " + " ".join(f"{n:>8d}" for n in sizes))
for nm in V: print(f"{nm:8s}" + " ".join(f"{st.median(res[(nm,n)]):8.3f}" for n in sizes))

